# Spring Boot host config. H2 in-memory in the same JVM; Flyway migrates the schema up on boot from
# db/migration; Actuator health is the readiness probe.

# In-memory H2 (dies with the JVM = clean per-run reset).
spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
spring.datasource.driver-class-name=org.h2.Driver
spring.datasource.username=sa
spring.datasource.password=
# Pooled connections are never retired: when HikariCP closes one at its default 30 min
# max-lifetime, this in-memory H2 closes under the remaining sessions and every later statement
# fails with "The database has been closed" while the health probe stays UP. 0 means no lifetime.
spring.datasource.hikari.max-lifetime=0

# Flyway owns the schema. JPA does not create tables.
spring.flyway.enabled=true
spring.jpa.hibernate.ddl-auto=none
# Close the persistence context at the end of the request, not during view rendering.
spring.jpa.open-in-view=false

# Readiness probe.
management.endpoints.web.exposure.include=health
management.endpoint.health.probes.enabled=true

# The SPA is served from src/main/resources/static (built there by bin/build); deep-link
# fallback is in SpaConfig.java.

# Audit sink: one record per line to this known file, so tests assert side-effects by reading it.
# bin/start passes an absolute path via AUDIT_FILE; default is .run/audit.log.
app.audit.file=${AUDIT_FILE:.run/audit.log}
-- A rate can carry a from-date: a grade may have several rates, each in force from its from-date
-- (none: from the beginning of time) until the next one. One rate per grade and from-date.
ALTER TABLE rate ADD COLUMN from_date DATE;
ALTER TABLE rate ADD COLUMN from_key DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'));
DROP INDEX rate_sheet_grade;
CREATE UNIQUE INDEX rate_sheet_grade_from ON rate (sheet_id, grade, from_key);
-- The user who opened a claim; none while it is DRAFT, or if it was voided without being opened.
-- That user cannot settle it (four eyes).
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(100);
-- A person's version: bumped on every save, so an edit made from a stale copy is refused.
ALTER TABLE person ADD COLUMN version BIGINT DEFAULT 0 NOT NULL;
-- A person's statements: each records the sheet's today when it was taken, the person's due-total
-- then (none when it was n/a) and how many of their claims counted. Listed oldest first (by id).
CREATE TABLE statement (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id   VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    taken_on   DATE           NOT NULL,
    due_total  DECIMAL(14, 2),
    claims     INT            NOT NULL
);
CREATE INDEX statement_sheet ON statement (sheet_id, person_id, id);
-- A claim bound by its person's last statement: it shows and totals the figure it had then (none
-- when it had no rate then) until the next statement rebinds or unbinds it.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(14, 2);
-- The sheet's periods: a name, unique on the sheet without regard to case, and a from and to date,
-- both inclusive. No two periods on a sheet overlap (checked by the service, under the sheet's lock).
CREATE TABLE period (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name      VARCHAR(100) NOT NULL,
    name_key  VARCHAR(100) GENERATED ALWAYS AS (LOWER(name)),
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CHECK (from_date <= to_date)
);
CREATE UNIQUE INDEX period_sheet_name ON period (sheet_id, name_key);
CREATE INDEX period_sheet_from ON period (sheet_id, from_date);
-- A period can be closed. Closing fixes its due-total at that moment (the due of the claims that
-- count whose date falls in it); later rate changes do not alter it. None while the period is open.
-- No claim dated inside a closed period can be added, edited or moved to another status.
ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_due DECIMAL(14, 2);
-- A person can be retired from a date. With a date set the person counts as retired at once,
-- whatever the date; no claim of theirs can be dated after it. None while not retired.
ALTER TABLE person ADD COLUMN retired_from DATE;
-- A person can be put on hold and taken off it again. While held, their OPEN claims count in no
-- live total; their SETTLED claims still do.
ALTER TABLE person ADD COLUMN held BOOLEAN DEFAULT FALSE NOT NULL;
-- A sheet assigns a role to a user name: clerk (the default for any name not listed) or steward.
CREATE TABLE sheet_role (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(100) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('clerk', 'steward'))
);
CREATE UNIQUE INDEX sheet_role_sheet_user ON sheet_role (sheet_id, user_name);
-- The sheet's clerk limit: a clerk settles a claim only when its due is at or below it. Null: no limit.
ALTER TABLE sheet ADD COLUMN clerk_limit DECIMAL(14, 2) CHECK (clerk_limit >= 0);
-- The sheet's floor: a claim's live due is never below it. Settled, stated and closed figures keep theirs.
ALTER TABLE sheet ADD COLUMN due_floor DECIMAL(14, 2) DEFAULT 1.00 NOT NULL CHECK (due_floor >= 0);
-- A sheet: everything else in the app is kept per sheet, keyed by its id.
CREATE TABLE sheet (
    id         VARCHAR(100) NOT NULL PRIMARY KEY,
    created_by VARCHAR(100) NOT NULL,
    created_at TIMESTAMP    NOT NULL
);
-- The sheet's terms: a claim is due by its date plus this many days. 14 on a new sheet.
ALTER TABLE sheet ADD COLUMN terms INTEGER DEFAULT 14 NOT NULL CHECK (terms >= 0);
-- The sheet's late percent: an overdue claim's due gains this percent of its figure for every full
-- 30 days it is overdue. 0.00 on a new sheet.
ALTER TABLE sheet ADD COLUMN late_pct DECIMAL(5, 2) DEFAULT 0.00 NOT NULL CHECK (late_pct >= 0);
-- A person's patrons: other people on the same sheet, each named once. Listed in the order they
-- were named (by id).
CREATE TABLE person_patron (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    patron_id BIGINT       NOT NULL REFERENCES person (id),
    CONSTRAINT person_patron_once UNIQUE (person_id, patron_id),
    CONSTRAINT person_patron_not_self CHECK (person_id <> patron_id)
);
CREATE INDEX person_patron_sheet ON person_patron (sheet_id, id);
-- A person's grades, each from a from-date (none: from the beginning of time) until their next
-- grade. The grade a person has so far applies from the beginning of time.
CREATE TABLE person_grade (
    person_id BIGINT     NOT NULL REFERENCES person (id),
    from_date DATE,
    grade     VARCHAR(1) NOT NULL CHECK (grade IN ('A', 'B', 'C'))
);
CREATE INDEX person_grade_person ON person_grade (person_id);
INSERT INTO person_grade (person_id, from_date, grade) SELECT id, NULL, grade FROM person;
ALTER TABLE person DROP COLUMN grade;
-- A correction: a claim with a negative amount, naming by number the SETTLED claim of the same
-- person that it corrects. The amount may now be below zero (only a correction's is), so the old
-- 0.00-or-more check goes with the column it was on: the amount moves to a column without it.
ALTER TABLE claim ADD COLUMN amount_signed DECIMAL(14, 2);
UPDATE claim SET amount_signed = amount;
ALTER TABLE claim DROP COLUMN amount;
ALTER TABLE claim ALTER COLUMN amount_signed RENAME TO amount;
ALTER TABLE claim ALTER COLUMN amount SET NOT NULL;
-- The number of the claim a correction corrects; none for any other claim.
ALTER TABLE claim ADD COLUMN corrects INT;
-- The sheet's policy date: a claim dated before it rounds half up, one dated on or after it half to
-- even. None (null) on a new sheet: the policy date is then the sheet's today.
ALTER TABLE sheet ADD COLUMN policy_date DATE;
-- Numbering per period: from the sheet's period-numbering-from date (none: off), a claim opened is
-- numbered within the period its date falls in (<period name>-<n>), or, in no period, in the
-- sheet's own X sequence (X-<n>). A claim's number, and the number a correction names, become text.
ALTER TABLE sheet ADD COLUMN period_numbering_from DATE;
ALTER TABLE sheet ADD COLUMN last_unperiod_claim_number INT DEFAULT 0 NOT NULL;
ALTER TABLE period ADD COLUMN last_claim_number INT DEFAULT 0 NOT NULL;
ALTER TABLE claim ALTER COLUMN claim_number SET DATA TYPE VARCHAR(120);
ALTER TABLE claim ALTER COLUMN corrects SET DATA TYPE VARCHAR(120);
-- A claim a clerk settles above the clerk limit goes to PENDING until a steward approves it
-- (SETTLED) or rejects it (back to OPEN). The status's allowed values gain PENDING, so the status
-- moves to a column whose check allows it.
ALTER TABLE claim ADD COLUMN status_pending VARCHAR(10) DEFAULT 'DRAFT' NOT NULL
    CHECK (status_pending IN ('DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'));
UPDATE claim SET status_pending = status;
ALTER TABLE claim DROP COLUMN status;
ALTER TABLE claim ALTER COLUMN status_pending RENAME TO status;
-- A person's claims are listed newest first by their place in the list: a claim takes the next
-- place when it is added, and again when it is moved to another person, so a moved claim is
-- listed as its new person's newest whatever its date. Existing claims keep their order (by id).
CREATE SEQUENCE claim_listed_seq;
ALTER TABLE claim ADD COLUMN listed BIGINT;
UPDATE claim SET listed = id;
ALTER SEQUENCE claim_listed_seq RESTART WITH (SELECT COALESCE(MAX(id), 0) + 1 FROM claim);
ALTER TABLE claim ALTER COLUMN listed SET DEFAULT NEXT VALUE FOR claim_listed_seq;
ALTER TABLE claim ALTER COLUMN listed SET NOT NULL;
CREATE INDEX claim_sheet_listed ON claim (sheet_id, listed);
-- Terms per grade: a grade with its own terms uses them; a grade without uses the sheet's terms.
CREATE TABLE sheet_grade_terms (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    grade    VARCHAR(1)   NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    terms    INTEGER      NOT NULL CHECK (terms >= 0),
    PRIMARY KEY (sheet_id, grade)
);
-- A claim's due-by is fixed when it is created, from the terms of its person's grade in force on
-- its date; later changes to the terms or the claim's date leave it as it is. Existing claims are
-- due by their date plus the sheet's terms, as they were.
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim SET due_by = DATEADD(DAY, (SELECT s.terms FROM sheet s WHERE s.id = claim.sheet_id), claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
-- A sheet's "today": the date every date-dependent decision and default date on the sheet uses.
-- It starts as the real date when the sheet is first loaded and can be changed on the screen.
ALTER TABLE sheet ADD COLUMN today DATE DEFAULT CURRENT_DATE NOT NULL;
-- A claim's status log: one line per status it has had, oldest first, with who made the change, the
-- sheet's today then and the claim's due as computed at that moment ('n/a' when it had none).
CREATE TABLE claim_log (
    claim_id BIGINT      NOT NULL REFERENCES claim (id),
    seq      INTEGER     NOT NULL,
    status   VARCHAR(10) NOT NULL CHECK (status IN ('DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID')),
    by_user  VARCHAR(100) NOT NULL,
    log_date DATE        NOT NULL,
    due      VARCHAR(20) NOT NULL,
    PRIMARY KEY (claim_id, seq)
);
-- A person may have several holds over time, each from a from-date to an optional to-date (none:
-- open-ended), both inclusive. A person held so far is held from the beginning of time, open-ended.
CREATE TABLE person_hold (
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE   NOT NULL,
    to_date   DATE
);
CREATE INDEX person_hold_person ON person_hold (person_id);
INSERT INTO person_hold (person_id, from_date, to_date) SELECT id, DATE '0001-01-01', NULL FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
-- A rate can carry a to-date: it is in force through it (none: until the grade's next rate).
ALTER TABLE rate ADD COLUMN to_date DATE;
ALTER TABLE rate ADD CONSTRAINT rate_to_after_from CHECK (to_date IS NULL OR from_date IS NULL OR to_date >= from_date);
-- The sheet's cap: a person's due-total is at most it, the rest their excess. Null: no cap.
ALTER TABLE sheet ADD COLUMN due_cap DECIMAL(14, 2) CHECK (due_cap >= 0);
-- Each person's due-total for a closed period, fixed when it was closed (the due of their claims
-- that count whose date falls in it), one row for every person on the sheet at that moment. A
-- person added later has none (shown as 0.00). Reopening removes them: the figures are live again.
CREATE TABLE period_person_due (
    period_id BIGINT         NOT NULL REFERENCES period (id),
    person_id BIGINT         NOT NULL,
    due       DECIMAL(14, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);
-- The sheet's settings that carry a figure, each recorded from a from-date (none: from the beginning
-- of time): the floor, the late percent, the terms (key terms, and terms-<grade> for a grade's own),
-- the clerk limit and the cap. The value in force on a date is the one with the latest from-date on
-- or before it; before every from-date a key has its starting value (floor 1.00, late percent 0.00,
-- terms 14; a grade's terms, the clerk limit and the cap none). A null value: none (no limit, no cap).
CREATE TABLE sheet_setting (
    sheet_id    VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    setting_key VARCHAR(20)    NOT NULL,
    from_date   DATE,
    amount      DECIMAL(14, 2) CHECK (amount >= 0)
);
CREATE INDEX sheet_setting_sheet ON sheet_setting (sheet_id);
-- The settings each sheet has so far apply from the beginning of time.
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, amount)
    SELECT id, 'floor', NULL, due_floor FROM sheet WHERE due_floor <> 1.00;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, amount)
    SELECT id, 'late-pct', NULL, late_pct FROM sheet WHERE late_pct <> 0.00;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, amount)
    SELECT id, 'terms', NULL, terms FROM sheet WHERE terms <> 14;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, amount)
    SELECT id, 'clerk-limit', NULL, clerk_limit FROM sheet WHERE clerk_limit IS NOT NULL;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, amount)
    SELECT id, 'cap', NULL, due_cap FROM sheet WHERE due_cap IS NOT NULL;
INSERT INTO sheet_setting (sheet_id, setting_key, from_date, amount)
    SELECT sheet_id, 'terms-' || grade, NULL, terms FROM sheet_grade_terms;
DROP TABLE sheet_grade_terms;
ALTER TABLE sheet DROP COLUMN due_floor;
ALTER TABLE sheet DROP COLUMN late_pct;
ALTER TABLE sheet DROP COLUMN terms;
ALTER TABLE sheet DROP COLUMN clerk_limit;
ALTER TABLE sheet DROP COLUMN due_cap;
-- An OPEN claim can be deferred to a date after the sheet's today: until the sheet's today reaches
-- it the claim counts in no total, is not overdue and cannot be settled.
ALTER TABLE claim ADD COLUMN deferred_until DATE;
-- A claim's proofs count, raised by one at a time. A claim whose due is above the proof threshold
-- in force on its date (a dated setting, key proof-threshold) cannot be settled or approved
-- while it has no proofs.
ALTER TABLE claim ADD COLUMN proofs INT NOT NULL DEFAULT 0;
-- The sheet's permission matrix: for an action (open, settle, void, reassign, close, reopen), the
-- roles that may take it, comma separated. An action with no row keeps the standing rule: open,
-- settle, void and close by clerk and steward; reassign and reopen by steward. Not dated.
CREATE TABLE sheet_permission (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    action   VARCHAR(20)  NOT NULL,
    roles    VARCHAR(200) NOT NULL,
    PRIMARY KEY (sheet_id, action)
);
-- A third role, viewer: sees the sheet and may change nothing. The role check is unnamed, so the
-- table is rebuilt with the wider check.
CREATE TABLE sheet_role_new (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(100) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('clerk', 'steward', 'viewer'))
);
INSERT INTO sheet_role_new (id, sheet_id, user_name, role) SELECT id, sheet_id, user_name, role FROM sheet_role;
DROP TABLE sheet_role;
ALTER TABLE sheet_role_new RENAME TO sheet_role;
ALTER TABLE sheet_role ALTER COLUMN id RESTART WITH (SELECT COALESCE(MAX(id), 0) + 1 FROM sheet_role);
CREATE UNIQUE INDEX sheet_role_sheet_user ON sheet_role (sheet_id, user_name);
-- People on a sheet, listed in the order they were added (by id).
CREATE TABLE person (
    id       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL,
    grade    VARCHAR(1)   NOT NULL CHECK (grade IN ('A', 'B', 'C'))
);
CREATE INDEX person_sheet ON person (sheet_id, id);
-- Grace days (none: off): when the sheet's today changes, every open period whose to-date plus the
-- grace days is before the new today is closed. Not dated.
ALTER TABLE sheet ADD COLUMN grace_days INT;
-- The number of the claim a claim was split off from; none for a claim not made by a split.
ALTER TABLE claim ADD COLUMN split_from VARCHAR(120);
-- The users watching a person, each at most once. Listed in the order they started watching (by id).
CREATE TABLE person_watch (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    user_name VARCHAR(100) NOT NULL,
    CONSTRAINT person_watch_once UNIQUE (person_id, user_name)
);
CREATE INDEX person_watch_sheet ON person_watch (sheet_id, user_name);
-- A steward's delegation of the steward role to a user for a from-date to a to-date, inclusive, by
-- the sheet's today. Listed in the order they were made (by id).
CREATE TABLE sheet_delegation (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id   VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name  VARCHAR(100) NOT NULL,
    from_date  DATE         NOT NULL,
    to_date    DATE         NOT NULL,
    steward    VARCHAR(100) NOT NULL,
    CHECK (to_date >= from_date)
);
CREATE INDEX sheet_delegation_sheet ON sheet_delegation (sheet_id, user_name);
-- Whether a steward has archived the sheet: an archived sheet stays visible and refuses every change.
ALTER TABLE sheet ADD COLUMN archived BOOLEAN NOT NULL DEFAULT FALSE;
-- A person's own terms, in days; null when they have none. A claim's due-by takes them first, before
-- the terms of the person's grade and the sheet's.
ALTER TABLE person ADD COLUMN terms INTEGER CHECK (terms >= 0);
-- The user whose open editor locks the claim for everyone else; none when unlocked. Released when the
-- editor is saved or cancelled, or the sheet's today changes.
ALTER TABLE claim ADD COLUMN locked_by VARCHAR(100);
-- A period can be soft-closed: its due-total and each person's due-total for it are fixed at that
-- moment (in closed_due and period_person_due, as for a closed period), but claims dated inside it
-- can still be added, edited, opened, settled and voided. Closing or reopening it clears the flag.
ALTER TABLE period ADD COLUMN soft_closed BOOLEAN DEFAULT FALSE NOT NULL;
-- A claim added while the period its date falls in was soft-closed is a late entry.
ALTER TABLE claim ADD COLUMN late_entry BOOLEAN DEFAULT FALSE NOT NULL;
-- A statement can be taken as of a date: every change that moves a figure records the sheet's today
-- when it was made (made_on), so the figures can be rebuilt as they stood at the end of a date. A
-- record from before this has none and counts as made from the beginning of time.

-- Each rate set, in the order set: the grade, its from-date and to-date, the percent and when it was set.
CREATE TABLE rate_log (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id  VARCHAR(100)  NOT NULL REFERENCES sheet (id),
    grade     VARCHAR(1)    NOT NULL,
    from_date DATE,
    to_date   DATE,
    pct       DECIMAL(5, 2) NOT NULL,
    made_on   DATE
);
CREATE INDEX rate_log_sheet ON rate_log (sheet_id, id);
INSERT INTO rate_log (sheet_id, grade, from_date, to_date, pct, made_on)
    SELECT sheet_id, grade, from_date, to_date, pct, NULL FROM rate;

-- Each setting value recorded, in the order recorded, and when.
CREATE TABLE sheet_setting_log (
    sheet_id    VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    seq         INT            NOT NULL,
    setting_key VARCHAR(20)    NOT NULL,
    from_date   DATE,
    amount      DECIMAL(14, 2),
    made_on     DATE
);
CREATE INDEX sheet_setting_log_sheet ON sheet_setting_log (sheet_id);
INSERT INTO sheet_setting_log (sheet_id, seq, setting_key, from_date, amount, made_on)
    SELECT sheet_id, ROW_NUMBER() OVER (PARTITION BY sheet_id ORDER BY setting_key) - 1, setting_key, from_date,
        amount, NULL FROM sheet_setting;

ALTER TABLE person ADD COLUMN added_on DATE;
ALTER TABLE person ADD COLUMN retired_on DATE;
ALTER TABLE person_grade ADD COLUMN made_on DATE;
ALTER TABLE person_hold ADD COLUMN made_on DATE;
ALTER TABLE claim ADD COLUMN deferred_on DATE;

-- The date a statement is taken as of is its taken_on; made_on is the sheet's today when it was taken.
ALTER TABLE statement ADD COLUMN made_on DATE;
UPDATE statement SET made_on = taken_on;
-- A person's name is unique on the sheet, compared without regard to case. Names are stored with
-- surrounding spaces removed, so the comparison key is just the lower-cased name.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(200) GENERATED ALWAYS AS (LOWER(name));
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
-- A person's claims: an amount (0.00 or more, two decimals), a date and a note (may be empty).
-- Listed newest first (by id).
CREATE TABLE claim (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id   VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    amount     DECIMAL(14, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE           NOT NULL,
    note       VARCHAR(1000)  NOT NULL
);
CREATE INDEX claim_sheet ON claim (sheet_id, person_id, id);
-- The sheet's rate for each grade: a percent with two decimals. A grade with no row has no rate.
CREATE TABLE rate (
    id       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    grade    VARCHAR(1)   NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    pct      DECIMAL(5, 2) NOT NULL CHECK (pct >= 0)
);
CREATE UNIQUE INDEX rate_sheet_grade ON rate (sheet_id, grade);
-- A claim's status: DRAFT when added; opened (OPEN), then settled (SETTLED); a DRAFT or OPEN
-- claim can be voided (VOID). Only OPEN and SETTLED claims count toward the totals.
ALTER TABLE claim ADD COLUMN status VARCHAR(10) NOT NULL DEFAULT 'DRAFT'
    CHECK (status IN ('DRAFT', 'OPEN', 'SETTLED', 'VOID'));
-- A claim's number: given when it is opened, the next on its sheet (1, 2, ...), with no gaps and
-- never reused. A draft has none; voiding a claim clears it. The sheet keeps the last number given.
ALTER TABLE sheet ADD COLUMN last_claim_number INT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN claim_number INT;
ALTER TABLE claim ADD CONSTRAINT claim_number_unique UNIQUE (sheet_id, claim_number);
-- A claim's due fixed when it is settled: the amount times the rate for its person's grade at that
-- moment (rounded half up to the cent). Later rate or grade changes do not alter it. None while
-- the claim is not settled, or when the grade had no rate when it was settled (it then stays live).
ALTER TABLE claim ADD COLUMN settled_due DECIMAL(14, 2);

