import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** Sign-in (a name, no password), loading a sheet by id, changing a sheet's today and archiving it. */
@RestController
@RequestMapping("/api")
public class SheetController {

    public record SignInRequest(@NotBlank @Size(max = 100) String name) {
    }

    public record SignInResponse(String name) {
    }

    public record LoadSheetRequest(@NotBlank @Size(max = 100) String id, @NotBlank @Size(max = 100) String user) {
    }

    public record SetTodayRequest(@NotBlank @Size(max = 100) String id, @NotBlank @Size(max = 100) String user,
            @NotNull LocalDate today) {
    }

    public record ArchiveSheetRequest(@NotBlank @Size(max = 100) String id, @NotBlank @Size(max = 100) String user) {
    }

    public record SheetResponse(String id, LocalDate today, boolean archived) {
    }

    private static SheetResponse response(Sheet sheet) {
        return new SheetResponse(sheet.getId(), sheet.getToday(), sheet.isArchived());
    }

    private final SheetService service;
    private final RoleService roles;

    public SheetController(SheetService service, RoleService roles) {
        this.service = service;
        this.roles = roles;
    }

    @PostMapping("/signin")
    public SignInResponse signIn(@Valid @RequestBody SignInRequest req) {
        return new SignInResponse(req.name().trim());
    }

    @PostMapping("/sheets/load")
    public SheetResponse load(@Valid @RequestBody LoadSheetRequest req) {
        return response(service.load(req.id().trim(), req.user().trim()));
    }

    @PostMapping("/sheets/today")
    public SheetResponse setToday(@Valid @RequestBody SetTodayRequest req) {
        // a viewer may not change the sheet's today (checked here: the role service depends on the sheet service)
        roles.refuseViewer(req.id().trim(), req.user().trim());
        return response(service.setToday(req.id().trim(), req.user().trim(), req.today()));
    }

    @PostMapping("/sheets/archive")
    public SheetResponse archive(@Valid @RequestBody ArchiveSheetRequest req) {
        // only a steward may archive the sheet (checked here: the role service depends on the sheet service)
        roles.refuseUnlessSteward(req.id().trim(), req.user().trim());
        return response(service.archive(req.id().trim(), req.user().trim()));
    }
}
package net.officefloor.hq.app.sheet;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.Instant;
import java.time.LocalDate;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.rollup.RollupService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** Loads a sheet by id; a sheet never loaded before is started empty, its today the real date. */
@Service
public class SheetService {

    private final SheetRepository sheets;
    private final RollupService rollup;
    private final PeriodRepository periods;
    private final Audit audit;
    private final ClaimRepository claims;

    public SheetService(SheetRepository sheets, RollupService rollup, PeriodRepository periods, Audit audit,
            ClaimRepository claims) {
        this.audit = audit;
        this.claims = claims;
        this.sheets = sheets;
        this.rollup = rollup;
        this.periods = periods;
    }

    @Transactional
    public Sheet load(String id, String user) {
        return sheets.findById(id).orElseGet(() -> {
            try {
                return sheets.saveAndFlush(new Sheet(id, user, Instant.now(), LocalDate.now()));
            } catch (DataIntegrityViolationException e) {
                // another user started the same sheet at the same moment
                return sheets.findById(id).orElseThrow(() -> e);
            }
        });
    }

    /** The sheet's today, for any date-dependent decision or default date on it. */
    @Transactional(readOnly = true)
    public LocalDate today(String id) {
        return sheets.findById(id).map(Sheet::getToday).orElseGet(LocalDate::now);
    }

    /** The sheet as the store holds it now; a sheet never loaded reads as a new one, today the real date. */
    @Transactional(readOnly = true)
    public Sheet sheet(String id) {
        return sheets.findById(id).orElseGet(() -> new Sheet(id, null, null, LocalDate.now()));
    }

    /** The sheet's clerk limit in force on its today: the most a clerk may settle a claim's due at; null for no limit. */
    @Transactional(readOnly = true)
    public BigDecimal clerkLimit(String id) {
        return sheets.findById(id).map(Sheet::getClerkLimit).orElse(null);
    }

    /** A person's due-total held to the sheet's cap in force on its today (none: as it is; n/a stays n/a). */
    @Transactional(readOnly = true)
    public BigDecimal capped(String id, BigDecimal dueTotal) {
        return sheets.findById(id).map(s -> s.capped(dueTotal)).orElse(dueTotal);
    }

    /** Refuse (423) any change to an archived sheet: it stays visible and may not be changed. */
    // a refusal leaves the caller's transaction usable (a bulk action refuses one claim and goes on)
    @Transactional(readOnly = true, noRollbackFor = ResponseStatusException.class)
    public void refuseIfArchived(String id) {
        if (sheet(id).isArchived()) {
            throw new ResponseStatusException(HttpStatus.LOCKED, "This sheet is archived and may not be changed.");
        }
    }

    /** Archive the sheet; refused (409) when it is already archived. The caller checks the user is a steward. */
    @Transactional
    public Sheet archive(String id, String user) {
        load(id, user);
        Sheet sheet = lock(id);
        if (sheet.isArchived()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "This sheet is already archived.");
        }
        sheet.archive();
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SHEET_ARCHIVED sheet=" + id + " by=" + user);
        return saved;
    }

    /** Lock the sheet until the caller's transaction ends; refused (404) when there is no such sheet. */
    @Transactional
    public Sheet lock(String id) {
        return sheets.findLockedById(id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
    }

    /**
     * The next number for a claim dated {@code date} opened on the sheet, with no gaps and never
     * reused. Sheet-wide (1, 2, ...) unless the sheet numbers by period on its today: then within
     * the period the date falls in ({@code <period name>-<n>}), or in no period its X sequence
     * ({@code X-<n>}), each counting from 1. The sheet stays locked until the caller's transaction
     * ends, so two claims opened at the same moment take different numbers.
     */
    @Transactional
    public String nextClaimNumber(String id, LocalDate date) {
        Sheet sheet = lock(id);
        if (!sheet.numbersByPeriod()) {
            int number = sheet.nextClaimNumber();
            sheets.saveAndFlush(sheet);
            return String.valueOf(number);
        }
        Optional<Period> period = periods.findBySheetIdAndFromDateLessThanEqualAndToDateGreaterThanEqual(id, date,
                date);
        if (period.isPresent()) {
            int number = period.get().nextClaimNumber();
            periods.saveAndFlush(period.get());
            return period.get().getName() + "-" + number;
        }
        int number = sheet.nextUnperiodClaimNumber();
        sheets.saveAndFlush(sheet);
        return "X-" + number;
    }

    /**
     * Close an open period, fixing its due-total now, and record it ({@code auto=yes} when closed by
     * a change of the sheet's today). The caller holds the sheet.
     */
    @Transactional
    public Period closePeriod(String id, String user, Period period, boolean auto) {
        period.close(rollup.dueBetweenByPerson(id, period.getFromDate(), period.getToDate()));
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_CLOSED sheet=" + id + " by=" + user + " period=" + saved.getName() + " total="
                + saved.getClosedDue().setScale(2, RoundingMode.UNNECESSARY).toPlainString() + (auto ? " auto=yes" : ""));
        return saved;
    }

    /** Soft-close an open period, fixing its due-total now, and record it. The caller holds the sheet. */
    @Transactional
    public Period softClosePeriod(String id, String user, Period period) {
        period.softClose(rollup.dueBetweenByPerson(id, period.getFromDate(), period.getToDate()));
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_SOFT_CLOSED sheet=" + id + " by=" + user + " period=" + saved.getName()
                + " total=" + saved.getClosedDue().setScale(2, RoundingMode.UNNECESSARY).toPlainString());
        return saved;
    }

    /**
     * Change the sheet's today. With grace days set, every open (not soft-closed) period whose to-date
     * plus the grace days is before the new today is then closed, in order of their to-dates. A new today releases
     * every claim editor's lock.
     */
    @Transactional
    public Sheet setToday(String id, String user, LocalDate today) {
        refuseIfArchived(id);
        load(id, user);
        // hold the sheet so no claim changes while periods close
        Sheet sheet = lock(id);
        RollupService.Snapshot before = rollup.snapshot(id);
        boolean moved = !today.equals(sheet.getToday());
        sheet.setToday(today);
        Sheet saved = sheets.saveAndFlush(sheet);
        Integer grace = saved.getGraceDays();
        if (grace != null) {
            for (Period period : periods.findBySheetIdAndClosedFalseOrderByToDateAsc(id)) {
                // a soft-closed period keeps the figures it fixed: only an open one closes by grace days
                if (!period.isSoftClosed() && period.getToDate().plusDays(grace).isBefore(today)) {
                    closePeriod(id, user, period, true);
                }
            }
        }
        // changing today has no audit line of its own, only the periods it closes and the figures it moves
        rollup.recordChanges(id, user, before);
        if (moved) {
            claims.unlockAll(id);
        }
        return saved;
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.LateCharge;
import net.officefloor.hq.app.claim.Rounding;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures as the screen shows them: each person's claimed, due-total and overdue-total
 * (the figures of their overdue claims that count, not capped), and the sheet's totals of each. A change takes a {@link #snapshot} before it alters anything
 * and calls {@link #recordChanges} after its own audit lines, which appends one ROLLUP line per
 * person whose figures moved (people in the order they were added; a new person counts as moved),
 * then a TOTALS line when any of the sheet's totals moved. A held person's OPEN claims count in none of
 * these (nor their PENDING ones), nor in a period's due-total; their SETTLED claims still do. So too a person whose
 * retirement date the sheet's today has reached. An overdue claim's figure has
 * its late charge added on top, and a live due is then never below the floor in force on its claim's date. A person's
 * due-total is at most the cap in force on the sheet's today, when there is one.
 */
@Service
public class RollupService {

    /** A person's figures: claimed, due-total (null for n/a) and overdue-total. */
    public record Figures(String name, BigDecimal claimed, BigDecimal dueTotal, BigDecimal overdueTotal) {
    }

    /** The sheet's figures: each person's by id, in the order they were added. */
    public record Snapshot(Map<Long, Figures> people) {

        public BigDecimal claimedTotal() {
            return people.values().stream().map(Figures::claimed).reduce(zero(), BigDecimal::add);
        }

        /** People's due-totals added up (n/a is no figure), trimmed as {@link #trimmed} says. */
        public BigDecimal dueTotal() {
            return trimmed(people.values().stream().map(Figures::dueTotal).filter(Objects::nonNull).toList());
        }

        /** People's overdue-totals added up, trimmed as {@link #trimmed} says. */
        public BigDecimal overdueTotal() {
            return trimmed(people.values().stream().map(Figures::overdueTotal).toList());
        }

        /** The sum of people's figures, leaving out the single highest and lowest when there are three or more. */
        private static BigDecimal trimmed(List<BigDecimal> figures) {
            BigDecimal sum = figures.stream().reduce(zero(), BigDecimal::add);
            if (figures.size() < 3) {
                return sum;
            }
            return sum.subtract(figures.stream().reduce(BigDecimal::max).orElseThrow())
                    .subtract(figures.stream().reduce(BigDecimal::min).orElseThrow());
        }
    }

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final Audit audit;

    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
            Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's figures as the store holds them now. */
    public Snapshot snapshot(String sheetId) {
        Sheet sheet = sheet(sheetId);
        LocalDate today = sheet.getToday();
        List<Rate> sheetRates = rates.findBySheetIdOrderByGradeAscFromDateAsc(sheetId);
        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            BigDecimal claimed = zero();
            BigDecimal due = zero();
            BigDecimal overdue = zero();
            boolean anyFigure = false;
            for (Claim claim : sheetClaims) {
                if (!claim.getPersonId().equals(person.getId()) || !person.counts(claim, today)) {
                    continue;
                }
                claimed = claimed.add(claim.getAmount());
                BigDecimal figure = figure(sheet, sheetRates, sheetClaims, person, claim);
                if (figure != null) {
                    anyFigure = true;
                    due = due.add(figure);
                    if (overdue(claim, today)) {
                        overdue = overdue.add(figure);
                    }
                }
            }
            // as on screen: n/a when the grade in force today has no rate today and no claim that
            // counts has a figure
            boolean none = inForce(sheetRates, person.gradeOn(today), today).isEmpty() && !anyFigure;
            figures.put(person.getId(), new Figures(person.getName(), claimed, none ? null : sheet.capped(due),
                    overdue));
        }
        return new Snapshot(figures);
    }

    /**
     * Each person's due of their claims whose date falls in from..to (both inclusive) and that
     * counted by the status they had at the end of the to-day (as their status log records it; a
     * claim with none by then does not), by person id, for every person on the sheet (0.00 when
     * none). Each counts at its figure as shown now.
     */
    public Map<Long, BigDecimal> dueBetweenByPerson(String sheetId, LocalDate from, LocalDate to) {
        Sheet sheet = sheet(sheetId);
        List<Rate> sheetRates = rates.findBySheetIdOrderByGradeAscFromDateAsc(sheetId);
        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
        Map<Long, BigDecimal> dues = new LinkedHashMap<>();
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            BigDecimal due = zero();
            for (Claim claim : sheetClaims) {
                if (!claim.getPersonId().equals(person.getId()) || claim.getDate().isBefore(from)
                        || claim.getDate().isAfter(to) || !claim.statusAt(to)
                                .map(status -> person.counts(claim, status, sheet.getToday())).orElse(false)) {
                    continue;
                }
                BigDecimal figure = figure(sheet, sheetRates, sheetClaims, person, claim);
                if (figure != null) {
                    due = due.add(figure);
                }
            }
            dues.put(person.getId(), due);
        }
        return dues;
    }

    /** Record, once the change commits, the figures that moved since the snapshot taken before it. */
    public void recordChanges(String sheetId, String user, Snapshot before) {
        Snapshot after = snapshot(sheetId);
        String prefix = " sheet=" + sheetId + " by=" + user;
        boolean moved = false;
        for (Map.Entry<Long, Figures> entry : after.people().entrySet()) {
            Figures now = entry.getValue();
            Figures was = before.people().get(entry.getKey());
            if (was != null && same(was.claimed(), now.claimed()) && same(was.dueTotal(), now.dueTotal())
                    && same(was.overdueTotal(), now.overdueTotal())) {
                continue;
            }
            moved = true;
            audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name() + " claimed=" + money(now.claimed())
                    + " due-total=" + money(now.dueTotal()) + " overdue-total=" + money(now.overdueTotal()));
        }
        if (moved && !(same(before.claimedTotal(), after.claimedTotal())
                && same(before.dueTotal(), after.dueTotal()) && same(before.overdueTotal(), after.overdueTotal()))) {
            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + money(after.claimedTotal()) + " due-total="
                    + money(after.dueTotal()) + " overdue-total=" + money(after.overdueTotal()));
        }
    }

    /**
     * A claim's figure as the screen shows it: the due fixed when settled, else the one bound by the
     * last statement (not while PENDING), else its live due (rounded as the claim rounds, see {@link Rounding}), with its late charge added on top, then raised to the floor (a correction's is not);
     * null when none.
     */
    private static BigDecimal figure(Sheet sheet, List<Rate> sheetRates, List<Claim> sheetClaims, Person person,
            Claim claim) {
        if (claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        BigDecimal figure = claim.isStated() && claim.getStatus() != ClaimStatus.PENDING ? claim.getStatedDue()
                : inForce(sheetRates, person.gradeOn(claim.getDate()), claim.getDate()).map(Rate::getPct)
                        .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2,
                                Rounding.mode(sheet, Rounding.dateOf(claim, sheetClaims))))
                        .orElse(null);
        return LateCharge.withCharge(sheet, claim, figure);
    }

    /** Whether a claim is overdue on the sheet's today: OPEN or PENDING, not deferred, and past its due-by. */
    private static boolean overdue(Claim claim, LocalDate today) {
        return claim.getStatus().isOpen() && !claim.isDeferredOn(today) && today != null && claim.getDueBy() != null
                && claim.getDueBy().isBefore(today);
    }

    private Sheet sheet(String sheetId) {
        return sheets.findById(sheetId).orElseGet(() -> new Sheet(sheetId, null, null, LocalDate.now()));
    }

    /** The grade's rate in force on a date, as {@link RateRepository#findInForce} picks it. */
    private static Optional<Rate> inForce(List<Rate> sheetRates, String grade, LocalDate date) {
        return sheetRates.stream().filter(r -> r.getGrade().equals(grade))
                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
                .max((a, b) -> a.getFromDate() == null ? -1 : b.getFromDate() == null ? 1
                        : a.getFromDate().compareTo(b.getFromDate()))
                .filter(r -> r.runsThrough(date));
    }

    private static boolean same(BigDecimal a, BigDecimal b) {
        return a == null ? b == null : b != null && a.compareTo(b) == 0;
    }

    private static BigDecimal zero() {
        return BigDecimal.ZERO.setScale(2);
    }

    private static String money(BigDecimal value) {
        return value == null ? "n/a" : value.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
    }
}

