test("as of view scenario 3", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-04-05");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "terms", "30");
  await ui.setSetting(pg_uma, "late-pct", "10.00");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-15");
  await ui.setSetting(pg_uma, "terms-B", "20");
  await ui.setSetting(pg_uma, "proof-threshold", "1.00");
  await ui.setSetting(pg_uma, "perm-close", "steward");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "5.00", "from": "2026-03-10", "to": "2026-03-12"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B"}));
  expect(await ui.generatePeriods(pg_uma, "2026-01-15", "2026-02-20")).toBe(2);
  await ui.setToday(pg_uma, "2026-05-11");
  expect(await ui.pasteClaims(pg_uma, "Ben,4.00,2026-02-25,")).toBe(1);
  const c_ben_0 = await ui.claimAt(pg_uma, p_ben, 0);
  expect(await ui.retire(pg_uma, p_cam, "2026-03-09")).toBe(true);
  expect(await ui.editClaim(pg_uma, c_ben_0, {"amount": "0.04"})).toBe(true);
  expect(await ui.hold(pg_uma, p_ben, {"from": "2026-02-10", "to": "2026-03-15"})).toBe(true);
  expect(await ui.statement(pg_uma, p_ben)).toBe(true);
  await ui.refresh(pg_uma);
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-status")).toHaveText("DRAFT");
