import { defineConfig, devices } from '@playwright/test';
export default defineConfig({ testDir: './dbg', workers: 1, reporter: [['list']],
  use: { baseURL: 'http://localhost:3000' },
  projects: [{ name: 'chromium', use: { ...devices['Desktop Chrome'], launchOptions: { args: ['--no-sandbox', '--disable-dev-shm-usage', '--disable-gpu'] } } }] });
EOF
export PORT=3000 AUDIT_FILE=$PWD/.run/audit.log; bin/start; for i in $(seq 60); do curl -fs localhost:3000/actuator/health >/dev/null && break; sleep 1; done; cd e2e && npx playwright test -c dbg.config.ts 2>&1 | grep -v "^\s*$" | head -40

